package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.AllowPasswordGrantVO;

class AllowPasswordGrantValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of allow password grant of tenant config")
  void test_allow_password_grant_value_holder_assign_plain_value() {
    Object holder = new Object();
    AllowPasswordGrantValueHolder<Object> value = new AllowPasswordGrantValueHolder<>(holder);
    Assertions.assertSame(holder, value.allowPasswordGrant(true), "Setters must return the holder");
    Assertions.assertTrue(value.getAllowPasswordGrantValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(true, value.getAllowPasswordGrant().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of allow password grant of tenant config")
  void test_allow_password_grant_value_holder_assign_value_object() {
    Object holder = new Object();
    AllowPasswordGrantValueHolder<Object> value = new AllowPasswordGrantValueHolder<>(holder);
    AllowPasswordGrantVO vo = AllowPasswordGrantVO.from(true);
    Assertions.assertFalse(value.getAllowPasswordGrantValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.allowPasswordGrant(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getAllowPasswordGrantValue().orElseThrow());
    Assertions.assertSame(holder, value.allowPasswordGrant(Optional.empty()));
    Assertions.assertFalse(value.getAllowPasswordGrantValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.allowPasswordGrant(Optional.of(vo)));
    Assertions.assertSame(vo, value.getAllowPasswordGrantValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of allow password grant of tenant config against the original")
  void test_allow_password_grant_value_holder_read() {
    Object holder = new Object();
    AllowPasswordGrantValueHolder<Object> value = new AllowPasswordGrantValueHolder<>(holder);
    AllowPasswordGrantVO vo = AllowPasswordGrantVO.from(true);
    AllowPasswordGrantVO other = AllowPasswordGrantVO.from(true);
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getAllowPasswordGrantValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readAllowPasswordGrant(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readAllowPasswordGrant(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.allowPasswordGrant(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readAllowPasswordGrant(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readAllowPasswordGrant(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of allow password grant of tenant config")
  void test_allow_password_grant_value_holder_unset() {
    Object holder = new Object();
    AllowPasswordGrantValueHolder<Object> value = new AllowPasswordGrantValueHolder<>(holder);
    AllowPasswordGrantVO vo = AllowPasswordGrantVO.from(true);
    value.allowPasswordGrant(vo);
    Assertions.assertSame(holder,
        value.unsetAllowPasswordGrantIfMatches("allowPasswordGrant_other"));
    Assertions.assertTrue(value.getAllowPasswordGrantValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetAllowPasswordGrantIfMatches("allowPasswordGrant"));
    Assertions.assertFalse(value.getAllowPasswordGrantValue().isPresent(),
        "The field name must clear the value");
    value.allowPasswordGrant(vo);
    Assertions.assertSame(holder, value.unsetAllowPasswordGrant());
    Assertions.assertFalse(value.getAllowPasswordGrantValue().isPresent(),
        "Unset must clear the value");
  }
}
